/* @autogenerated */
package net.civeira.phylax.feature.oauth.device.infrastructure.driver.html;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.UUID;

import jakarta.enterprise.context.RequestScoped;
import jakarta.ws.rs.CookieParam;
import jakarta.ws.rs.GET;
import jakarta.ws.rs.POST;
import jakarta.ws.rs.Path;
import jakarta.ws.rs.PathParam;
import jakarta.ws.rs.QueryParam;
import jakarta.ws.rs.core.Context;
import jakarta.ws.rs.core.HttpHeaders;
import jakarta.ws.rs.core.MultivaluedMap;
import jakarta.ws.rs.core.NewCookie;
import jakarta.ws.rs.core.Response;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.oauth.authentication.application.SessionManager;
import net.civeira.phylax.feature.oauth.authentication.infrastructure.driver.html.AuthorizeHtml;
import net.civeira.phylax.feature.oauth.authentication.infrastructure.driver.html.OidcCookieManager;
import net.civeira.phylax.feature.oauth.device.application.DeviceAuthorizationService;
import net.civeira.phylax.feature.oauth.device.domain.DeviceAuthorizationStatus;
import net.civeira.phylax.feature.oauth.theme.domain.gateway.DecoratePageGateway;

/**
 * User side of the device grant (RFC 8628 §3.3): the user enters or confirms the user code and
 * approves it with a session of the same tenant.
 *
 * <p>
 * The session cookie is {@code SameSite=None}, so the approval needs a double-submit token: the
 * form carries {@code csrf} and the {@code DEVICE_CSRF} cookie (SameSite=Lax) the same value. A
 * cross-site page cannot make a signed-in user approve the attacker's device (RFC 8628 §5.5).
 */
@Path("")
@RequestScoped
@RequiredArgsConstructor
public class DeviceVerificationHtml {

  /**
   * Cookie holding the double-submit token of the approval form.
   */
  public static final String DEVICE_CSRF = "DEVICE_CSRF";

  private final DeviceAuthorizationService deviceAuthorization;
  private final SessionManager sessions;
  private final DecoratePageGateway decorator;

  @GET
  @Path("oauth/openid/{tenant}/device/verify")
  public Response verify(final @PathParam("tenant") String tenant,
      @QueryParam("user_code") String userCode, @Context HttpHeaders headers) {
    var locale = headers.getAcceptableLanguages().isEmpty() ? java.util.Locale.getDefault()
        : headers.getAcceptableLanguages().get(0);
    String normalized = normalize(userCode);
    if (normalized.isEmpty()) {
      return form(tenant, "", locale);
    }
    var record = deviceAuthorization.findByUserCode(tenant, normalized);
    if (record == null) {
      return message(tenant, AuthorizeHtml.i18n(locale, "device.invalid-code"), locale);
    }
    if (record.isExpired()) {
      return message(tenant, AuthorizeHtml.i18n(locale, "device.expired-code"), locale);
    }
    if (record.getStatus() == DeviceAuthorizationStatus.APPROVED) {
      return message(tenant, AuthorizeHtml.i18n(locale, "device.already-approved"), locale);
    }
    if (record.getStatus() == DeviceAuthorizationStatus.DENIED) {
      return message(tenant, AuthorizeHtml.i18n(locale, "device.denied"), locale);
    }
    // verification_uri_complete: the code comes filled in (the stored one, never the raw input),
    // and the user still confirms it.
    return form(tenant, record.getUserCode(), locale);
  }

  @POST
  @Path("oauth/openid/{tenant}/device/verify")
  public Response formVerify(final @PathParam("tenant") String tenant,
      @CookieParam(OidcCookieManager.AUTH_SESSION_ID) String sessionId,
      @CookieParam(DEVICE_CSRF) String csrfCookie, final MultivaluedMap<String, String> form,
      @Context HttpHeaders headers) {
    var locale = headers.getAcceptableLanguages().isEmpty() ? java.util.Locale.getDefault()
        : headers.getAcceptableLanguages().get(0);
    String csrf = form.getFirst("csrf");
    if (csrf == null || csrfCookie == null
        || !MessageDigest.isEqual(csrf.getBytes(StandardCharsets.UTF_8),
            csrfCookie.getBytes(StandardCharsets.UTF_8))) {
      return Response.status(403).build();
    }
    String normalized = normalize(form.getFirst("user_code"));
    if (normalized.isEmpty()) {
      return message(tenant, AuthorizeHtml.i18n(locale, "device.code-required"), locale);
    }
    var record = deviceAuthorization.findByUserCode(tenant, normalized);
    if (record == null) {
      return message(tenant, AuthorizeHtml.i18n(locale, "device.invalid-code"), locale);
    }
    if (record.isExpired()) {
      return message(tenant, AuthorizeHtml.i18n(locale, "device.expired-code"), locale);
    }
    if (record.getStatus() != DeviceAuthorizationStatus.PENDING) {
      return message(tenant, AuthorizeHtml.i18n(locale, "device.not-pending"), locale);
    }
    if (sessionId == null || sessionId.isBlank()) {
      return message(tenant, AuthorizeHtml.i18n(locale, "device.auth-required"), locale);
    }
    return sessions.loadSession(sessionId, tenant).map(session -> {
      boolean approved =
          deviceAuthorization.approveByUserCode(tenant, normalized, session.getValidationData());
      return approved ? message(tenant, AuthorizeHtml.i18n(locale, "device.approved"), locale)
          : message(tenant, AuthorizeHtml.i18n(locale, "device.approval-failed"), locale);
    }).orElseGet(() -> message(tenant, AuthorizeHtml.i18n(locale, "device.auth-required"), locale));
  }

  /**
   * The user code form, with a fresh double-submit token.
   */
  private Response form(String tenant, String userCode, java.util.Locale locale) {
    String csrf = UUID.randomUUID().toString();
    NewCookie cookie =
        new NewCookie.Builder(DEVICE_CSRF).value(csrf).path("/oauth/openid/" + tenant).secure(true)
            .httpOnly(true).sameSite(NewCookie.SameSite.LAX).build();
    return Response
        .ok(decorator.getFullPage(tenant, AuthorizeHtml.i18n(locale, "device.title"),
            "<h1>" + AuthorizeHtml.i18n(locale, "device.title") + "</h1><p>"
                + AuthorizeHtml.i18n(locale, "device.ask-help") + "</p>"
                + "<form method=\"POST\"><input type=\"hidden\" name=\"csrf\" value=\"" + csrf
                + "\" /><label>" + AuthorizeHtml.i18n(locale, "device.user-code")
                + "<input type=\"text\" name=\"user_code\" value=\"" + userCode + "\" /></label>"
                + "<input class=\"primary-button action-button\" type=\"submit\" value=\""
                + AuthorizeHtml.i18n(locale, "device.continue") + "\" />" + "</form>",
            locale))
        .type("text/html").cookie(cookie).header("Cache-Control", "no-store").build();
  }

  private Response message(String tenant, String message, java.util.Locale locale) {
    return Response
        .ok(decorator.getFullPage(tenant, AuthorizeHtml.i18n(locale, "device.title"),
            "<h1>" + AuthorizeHtml.i18n(locale, "device.title") + "</h1><p>" + message + "</p>"
                + "<form method=\"GET\">" + "<input class=\"inline\" type=\"submit\" value=\""
                + AuthorizeHtml.i18n(locale, "device.back") + "\" />" + "</form>",
            locale))
        .type("text/html").build();
  }

  private String normalize(String value) {
    if (value == null) {
      return "";
    }
    String code = value.trim().toUpperCase().replace(" ", "").replace("-", "");
    if (code.length() == 8) {
      return code.substring(0, 4) + "-" + code.substring(4);
    }
    return code;
  }
}
